// KIT: every UI pattern variant seen in CollabCRM, rendered from verbatim DOM (src/data/patterns.js, generated by _tools/kit_patterns.py). Route /patterns?tab=…
// DIVERGES: KIT-only page (the card + caption around each snippet are not a CollabCRM screen). Caption class = CAP in components/super/ui.jsx.
import { useSearchParams } from 'react-router-dom'
import AppShell from '../components/AppShell.jsx'
import PageFrame from '../components/cc/PageFrame.jsx'
import PillTabs from '../components/cc/PillTabs.jsx'
import { CAP, CARD } from '../components/super/ui.jsx'
import { PEOPLE_NAV } from '../data/nav.js'
import PATTERNS from '../data/patterns.js'

export default function Patterns() {
  const names = Object.keys(PATTERNS)
  const [qs, setQs] = useSearchParams()
  const tab = names.includes(qs.get('tab')) ? qs.get('tab') : names[0]
  return (
    <AppShell portal="people" nav={PEOPLE_NAV} active="">
      <PageFrame crumbs={[{ label: 'Patterns' }]}>
        <PillTabs tabs={names.map((n) => ({ key: n, label: `${n} (${PATTERNS[n].length})` }))} active={tab} onChange={(k) => setQs({ tab: k })} />
        <div className="grid gap-3 pt-4">
          {PATTERNS[tab].map((v, i) => (
            <div key={i} className={`${CARD} p-4`}>
              <p className={CAP}>Variant {i + 1} · seen {v.count}× · copy from {v.source}</p>
              <div className="pt-3 overflow-x-auto" dangerouslySetInnerHTML={{ __html: v.snippet }} />
            </div>
          ))}
        </div>
      </PageFrame>
    </AppShell>
  )
}
